SCALE=.227185/1024

def uv_world(uv,z):
    u,v=uv
    return np.array([-.1+(512-v)*SCALE,(512-u)*SCALE,z])

def start_component(cid,depth=.002,speed=.006,practice=False):
    global active, active_rows, active_index, active_cid, active_practice
    p=np.load(OUT/f'path_{cid}.npy')
    xyz=np.array([uv_world(uv,paper_z-depth) for uv in p])
    if practice:
        xyz[:,1]-=.1856
        xyz[:,1]+=(p[0,0]-512)*SCALE # align starting point centre practice; small component fits width
    dip()
    move([*xyz[0,:2],.06],f'c{cid}_above',speed=.08)
    move(xyz[0],f'c{cid}_down',speed=.008,hold=.3,cameras=['practice_cam' if practice else 'canvas_cam'])
    active_rows=np.array(waypath(xyz,speed)); active_index=0;active_cid=cid;active_practice=practice
    print('PATH_READY',cid,len(active_rows),'simulation seconds',len(active_rows)*.05,flush=True)

def advance_component(chunks=5):
    global active_index
    cam='practice_cam' if active_practice else 'canvas_cam'
    for _ in range(chunks):
        if active_index>=len(active_rows):break
        a=active_rows[active_index:active_index+190]
        res=submit(a,f'component{active_cid}_{"practice" if active_practice else "main"}_{active_index}',cameras=[cam],video='none')
